$_MODULE['<{retractationcommande}prestashop>demande_ecbc815f858a7d4a0ff0fe67f6eea2a3'] = 'ORDINE NON SPEDITO — annullamento prima della spedizione: nessuna restituzione di prodotto prevista. Da verificare: esclusioni legali (art. L221-28). Ricordi di bloccare la spedizione prima della convalida.';
